import "server-only";
import { DEFAULT_GRAMMAR, DEFAULT_MOVES, type AngleGrammar, type CameraMove } from "./catalog";
// Generated by scripts/sync-workflows.mjs from ../workflows (the source of truth).
// Static imports so the graphs are bundled into every deployment.
import angleGraph from "@/workflows/angle.api.json";
import angleGgufGraph from "@/workflows/angle.gguf.api.json";
import rawManifest from "@/workflows/manifest.json";
import moveGraph from "@/workflows/move.api.json";

export type Binding = { node: string; field: string };

export type StageManifest = {
  file: string;
  inputs: Record<string, Binding>;
  outputs: Record<string, string>;
  models?: { file: string; folder: string; url?: string }[];
};

export type Manifest = {
  angle: StageManifest;
  move: StageManifest;
  angleGrammar: AngleGrammar;
  cameraMoves: CameraMove[];
};

export type Stage = "angle" | "move";

const raw = rawManifest as unknown as Partial<Manifest>;

type RawStop = { id: string; deg?: number; token: string; label?: string; scale?: number; radius?: number };

const titleCase = (id: string) => id.replace(/(^|-)(\w)/g, (_, sep, c) => (sep ? " " : "") + c.toUpperCase());

// The manifest is written for the models (ids, degrees, prompt tokens); labels and
// rig radii are UI concerns, so fill them from the catalog when the manifest omits them.
function normalizeGrammar(g: Partial<Record<keyof AngleGrammar, unknown>> | undefined): AngleGrammar {
  if (!g) return DEFAULT_GRAMMAR;
  const label = (list: { id: string; label: string }[], s: RawStop) => s.label ?? list.find((d) => d.id === s.id)?.label ?? titleCase(s.id);
  const stops = (key: "azimuths" | "elevations") =>
    (g[key] as RawStop[]).map((s) => ({ id: s.id, deg: s.deg ?? 0, token: s.token, label: label(DEFAULT_GRAMMAR[key], s) }));
  return {
    azimuths: stops("azimuths"),
    elevations: stops("elevations"),
    distances: (g.distances as RawStop[]).map((s) => ({
      id: s.id,
      token: s.token,
      label: label(DEFAULT_GRAMMAR.distances, s),
      radius: s.radius ?? DEFAULT_GRAMMAR.distances.find((d) => d.id === s.id)?.radius ?? 3.4 * (s.scale ?? 1),
    })),
    template: (g.template as string) ?? DEFAULT_GRAMMAR.template,
  };
}
if (!raw.angle || !raw.move) throw new Error("workflows/manifest.json must define angle and move stages");

const manifest: Manifest = {
  angle: raw.angle,
  move: raw.move,
  angleGrammar: normalizeGrammar(raw.angleGrammar),
  cameraMoves: raw.cameraMoves?.length ? raw.cameraMoves : DEFAULT_MOVES,
};

type Graph = Record<string, unknown>;
const graphs: Record<Stage, Graph> = { angle: angleGraph, move: moveGraph };

// Same node ids and bindings, different loaders (e.g. GGUF for Apple Silicon). Chosen per deployment.
const variants: Record<string, Partial<Record<Stage, Graph>>> = { gguf: { angle: angleGgufGraph } };

export function workflowVariant(): string | null {
  const v = process.env.COMFY_WORKFLOW_VARIANT?.trim();
  if (!v) return null;
  if (!variants[v]) throw new Error(`Unknown COMFY_WORKFLOW_VARIANT "${v}" (known: ${Object.keys(variants).join(", ")})`);
  return v;
}

export async function getManifest(): Promise<Manifest> {
  return manifest;
}

export async function loadGraph(stage: Stage): Promise<Record<string, unknown>> {
  const v = workflowVariant();
  return (v && variants[v][stage]) || graphs[stage];
}
